// The "/" landing page preloads this tree behind its empty-state card
// so it never depends on a live database round trip. The JSON is a real
// /api/trees response for the default word, regenerated by
// `npm run snapshot:default-tree` against a running dev server.
import type { TreeSlice } from '../shared/types';
import defaultTreeSlice from './defaultTree.json' with { type: 'json' };

export const DEFAULT_LANG = 'en';
export const DEFAULT_HEADWORD = 'etymology';

export const DEFAULT_TREE_SLICE = defaultTreeSlice as TreeSlice;
